pub const FEATURE_ID:&str="AFA-epistemic-P32-F01";pub const CONTRACT_VERSION:&str="epistemic-local-evidence-closure/1.0";pub const CONTENT_TYPE:&str="application/vnd.aurora.epistemic.evidence-closure-card-1+json";pub const BOUNDARY:&str="preclinical-research-only; no human-subject or clinical-source data; no diagnosis, treatment, triage, enrollment, or clinical decisions";
