#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct EvidenceClosureArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:ContentHash,pub semantic_loss:Vec<String>,pub assertion_digests:Vec<ContentHash>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct EvidenceClosureCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub purpose:String,pub disposition:String,pub assertion_order:Vec<String>,pub supported_order:Vec<String>,pub contradicted_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub source_order:Vec<String>,pub uncertainty_order:Vec<String>,pub competing_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub replay_identity:ContentHash,pub closure_digest:ContentHash,pub artifact:EvidenceClosureArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum EvidenceClosureError{#[error("invalid evidence-closure request: {0}")]Invalid(String),#[error("evidence-closure card failed validation: {0}")]Output(String)}
fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn nonempty(v:&str)->bool{!v.trim().is_empty()}
pub fn manifest(id:&str,version:&str,scale:&str,mode:&str)->serde_json::Value{json!({"schema_version":"1.0.0","capability_id":id,"version":version,"owner_crate":"epistemic","consumers":["evidence compiler","retrieval synthesizer","decision-section compiler","release auditor"],"behavior":format!("qualify evidence-backed assertion closure at {scale} ({mode})"),"value":"keeps uncertainty, contradictions, competing explanations, and negative evidence visible instead of manufacturing confidence","input_schema":"EvidenceClosureRequest4@1","output_schema":"EvidenceClosureCard7@1","effects":["emit:evidence-closure-card","retain:uncertainty","block:unsupported-claim"],"permissions":["read:local-assertions"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
impl EvidenceClosureCard7{pub fn validate(&self)->Result<(),EvidenceClosureError>{if self.schema_version!="1.0.0"||!nonempty(&self.contract_version)||!nonempty(&self.feature_id)||!nonempty(&self.mode)||!nonempty(&self.scale)||!nonempty(&self.request_id)||!nonempty(&self.purpose)||self.boundary!=BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.assertion_order.is_empty()||!ordered(&self.assertion_order)||!ordered(&self.supported_order)||!ordered(&self.contradicted_order)||!ordered(&self.unknown_order)||!ordered(&self.omitted_order)||!ordered(&self.source_order)||!ordered(&self.uncertainty_order)||!ordered(&self.competing_order)||!ordered(&self.negative_evidence_order)||!digest(&self.replay_identity)||!digest(&self.closure_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.closure_digest||self.artifact.boundary!=BOUNDARY{return Err(EvidenceClosureError::Output("evidence identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.assertion_order.iter().cloned());let states=self.supported_order.iter().chain(&self.contradicted_order).chain(&self.unknown_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.assertion_order.len()||states.len()!=ids.len()||BTreeSet::from_iter(states)!=ids{return Err(EvidenceClosureError::Output("assertion states do not partition".into()))}Ok(())}}
pub fn qualify(request:&EvidenceClosureRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<EvidenceClosureCard7,EvidenceClosureError>{if !nonempty(&request.request_id)||!nonempty(&request.purpose)||request.assertions.is_empty()||request.required_assertion_order.is_empty()||request.required_source_order.is_empty()||!digest(&request.replay_identity)||request.boundary!=BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ordered(&request.required_assertion_order)||!ordered(&request.required_source_order)||!ordered(&request.adversarial_events){return Err(EvidenceClosureError::Invalid("evidence identity, requirements, digest, ordering, locality, or boundary is invalid".into()))}let mut rows=request.assertions.clone();rows.sort_by(|a,b|a.assertion_id.cmp(&b.assertion_id));let mut seen=BTreeSet::new();let mut order=Vec::new();let mut supported=BTreeSet::new();let mut contradicted=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut sources=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut competing=BTreeSet::new();let mut negative=BTreeSet::new();let mut digests=BTreeSet::new();for a in &rows{if !seen.insert(a.assertion_id.clone())||!nonempty(&a.assertion_id)||!nonempty(&a.source_id)||!nonempty(&a.statement)||!digest(&a.evidence_digest)||!a.local||!a.aggregate_only{return Err(EvidenceClosureError::Invalid("assertion identity, source, evidence, or locality is invalid".into()))}order.push(a.assertion_id.clone());sources.insert(a.source_id.clone());uncertainty.insert(format!("{}:{}",a.assertion_id,a.uncertainty_milli));digests.insert(a.evidence_digest.clone());if a.competing_explanation{competing.insert(a.assertion_id.clone());}if a.negative_result{negative.insert(format!("{}:negative-result",a.assertion_id));}if a.policy_epoch==0{unknown.insert(a.assertion_id.clone());}else if a.contradicted{contradicted.insert(a.assertion_id.clone());}else if !request.required_assertion_order.contains(&a.assertion_id)||!request.required_source_order.contains(&a.source_id){contradicted.insert(a.assertion_id.clone());}else if a.evidence_digest==request.replay_identity{omitted.insert(a.assertion_id.clone());}else{supported.insert(a.assertion_id.clone());}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty()||request.action_count>request.action_budget;if global{omitted.extend(order.iter().cloned());supported.clear();contradicted.clear();unknown.clear();}let missing=!request.required_assertion_order.iter().all(|a|seen.contains(a))||!request.required_source_order.iter().all(|s|sources.contains(s));let disposition=if global{"blocked"}else if missing{"unknown"}else if !contradicted.is_empty()||!unknown.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let mut payload=json!({"schema_version":"1.0.0","contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"purpose":request.purpose,"disposition":disposition,"assertion_order":order,"supported_order":supported.into_iter().collect::<Vec<_>>(),"contradicted_order":contradicted.into_iter().collect::<Vec<_>>(),"unknown_order":unknown.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"source_order":sources.into_iter().collect::<Vec<_>>(),"uncertainty_order":uncertainty.into_iter().collect::<Vec<_>>(),"competing_order":competing.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let hash=ContentHash::of_value(&payload).map_err(|e|EvidenceClosureError::Output(e.to_string()))?;payload["closure_digest"]=json!(hash);payload["artifact"]=json!({"artifact_id":format!("epistemic-evidence:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":hash,"semantic_loss":payload["omitted_order"],"assertion_digests":digests.into_iter().collect::<Vec<_>>(),"boundary":BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("emit:evidence-closure:{}",request.request_id)]}else{vec!["block:unsupported-claim".to_string()]});let out:EvidenceClosureCard7=serde_json::from_value(payload).map_err(|e|EvidenceClosureError::Output(e.to_string()))?;out.validate()?;Ok(out)}
